<?php
declare(strict_types=1);
function prod_cost_report(int $run):array{
 $r=prod_run($run);$p=prod_plan((int)$r['plan_id']);$quote=pricing_detail((int)$p['quotation_id']);$usage=crm_query('SELECT u.*,x.step_id,x.revision_number,a.state AS attempt_state FROM nd_prod_step_attempts x JOIN nd_ai_attempts a ON a.task_id=x.ai_task_id JOIN nd_ai_usage u ON u.attempt_id=a.id JOIN nd_prod_steps s ON s.id=x.step_id WHERE s.run_id=? UNION ALL SELECT u.*,NULL AS step_id,0 AS revision_number,a.state AS attempt_state FROM nd_prod_plans p JOIN nd_ai_artifacts f ON f.id=p.ai_artifact_id JOIN nd_ai_attempts a ON a.task_id=f.task_id JOIN nd_ai_usage u ON u.attempt_id=a.id WHERE p.id=? ORDER BY id',[$run,$p['id']])->fetchAll();
 $categories=['provider','owner_labor','testing','tools','hosting','external','other','tax_and_fees'];$known=0;$missing=[];$records=[];
 foreach($categories as $category){$e=crm_query('SELECT * FROM nd_prod_expenses WHERE run_id=? AND category=? ORDER BY id DESC LIMIT 1',[$run,$category])->fetch();if(!$e||$e['provenance']!=='verified'||$e['currency']!=='RUB')$missing[]=$category;if($e){$records[]=$e;if($e['currency']==='RUB')$known+=(int)$e['amount_minor'];}}
 $complete=!$missing;$price=(int)$quote['calculation']['selling_minor'];$estimated=(int)$quote['calculation']['cost_pool_minor']+(int)$quote['calculation']['tax_minor']+(int)$quote['calculation']['payment_fee_minor'];
 return ['ok'=>true,'run_id'=>$run,'approved_price_minor'=>$price,'currency'=>'RUB','estimated_all_cost_minor'=>$estimated,'estimated_contribution_minor'=>$quote['calculation']['contribution_minor'],'known_recorded_minor'=>$known,'actual_recorded_minor'=>$complete?$known:null,'actual_contribution_minor'=>$complete?$price-$known:null,'cost_variance_minor'=>$complete?$known-$estimated:null,'unrecorded_categories'=>$missing,'status'=>$complete?'COMPLETE':'PARTIAL','expenses'=>$records,'provider_usage'=>$usage,'meaning'=>'Latest owner expense totals per category; provider observations shown separately and not double-counted. NULL is unknown, not zero. No automatic financial transactions.'];
}
function prod_expense(int $run,array $d):array{
 return crm_idempotent('production:expense:'.$run,$d,function()use($run,$d){prod_run($run,true);$cat=$d['category']??'';if(!in_array($cat,['provider','owner_labor','testing','tools','hosting','external','other','tax_and_fees'],true)||!in_array($d['currency']??'', ['RUB','USD','EUR'],true)||!is_bool($d['verified']??null))crm_fail(422,'Проверьте категорию, валюту и подтверждение расхода.');$amount=bill_minor($d['amount']??null);$hours=isset($d['hours'])?bill_minor($d['hours'],3):null;$source=cc_text($d,'source',1000);crm_query('INSERT INTO nd_prod_expenses(run_id,category,amount_minor,currency,hours_milli,provenance,owner_id,source) VALUES (?,?,?,?,?,?,1,?)',[$run,$cat,$amount,$d['currency'],$hours,$d['verified']?'verified':'owner_entered',$source]);return ['ok'=>true,'id'=>(int)db()->lastInsertId()];});
}
function prod_finish(int $run,array $d):array{
 return crm_idempotent('production:finish:'.$run,$d,function()use($run,$d){$r=prod_run($run,true);$p=prod_plan((int)$r['plan_id']);prod_current_source($p,true);crm_version($d,$r);if($r['state']!=='DELIVERED'||($d['confirm']??false)!==true)crm_fail(409,'Завершение требует отдельного подтверждения после приёмки.');
  $pkg=crm_query("SELECT * FROM nd_prod_packages WHERE run_id=? AND state='DELIVERED' ORDER BY id DESC LIMIT 1",[$run])->fetch();$accepted=$pkg?cc_revision(['type'=>'owner','id'=>1],(int)$pkg['revision_id']):null;if(!$accepted||($accepted['decision']['decision']??'')!=='approved')crm_fail(409,'Клиент ещё не принял результат через существующее согласование.');
  $stages=crm_query("SELECT COUNT(*) AS total,SUM(status='completed') AS done FROM nd_project_stages WHERE project_id=?",[$p['project_id']])->fetch();if(!(int)$stages['total']||(int)$stages['total']!==(int)$stages['done']||crm_query("SELECT 1 FROM nd_tasks t JOIN nd_task_projects x ON x.task_id=t.id WHERE x.project_id=? AND t.status NOT IN ('done','cancelled') AND t.archived_at IS NULL LIMIT 1",[$p['project_id']])->fetchColumn())crm_fail(409,'Сначала подтвердите завершение реальных этапов и задач CRM.');
  if(crm_query("SELECT 1 FROM nd_projects WHERE order_id=? AND id<>? AND archived_at IS NULL AND status<>'completed' LIMIT 1",[$p['order_id'],$p['project_id']])->fetchColumn())crm_fail(409,'Другие проекты этого заказа ещё не завершены.');
  foreach(['projects'=>(int)$p['project_id'],'orders'=>(int)$p['order_id']] as $kind=>$id){$row=crm_record($kind,$id,true);$intermediate=$kind==='projects'?'active':'in_progress';if($row['status']==='planned'||$row['status']==='confirmed'){crm_transition($kind,$row['status'],$intermediate);crm_query('UPDATE '.crm_table($kind).' SET status=?,version=version+1 WHERE id=?',[$intermediate,$id]);$row['status']=$intermediate;}crm_transition($kind,$row['status'],'completed');crm_query("UPDATE ".crm_table($kind)." SET status='completed',completed_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?",[$id]);crm_event($kind,$id,'updated',crm_record($kind,$id));}
  prod_run_state($r,'COMPLETED','owner_completed_after_customer_acceptance');crm_query("UPDATE nd_prod_plans SET state='COMPLETED',version=version+1 WHERE id=?",[$p['id']]);$report=prod_cost_report($run);$json=ai_json($report);crm_query('INSERT INTO nd_prod_profitability(run_id,body,checksum) VALUES (?,?,?)',[$run,$json,hash('sha256',$json)]);return ['ok'=>true,'id'=>$run,'profitability'=>$report];
 });
}
